insert into public.beverages (
  id,
  name,
  category,
  subtype,
  brand,
  origin,
  description,
  image_url,
  official_tags,
  flavour_source_url,
  origin_source_url,
  image_source_url,
  catalogue_source,
  catalogue_number,
  workbook_row,
  is_published
)
select
  id,
  name,
  category,
  subtype,
  brand,
  origin,
  description,
  image_url,
  official_tags,
  flavour_source_url,
  origin_source_url,
  image_source_url,
  catalogue_source,
  catalogue_number,
  workbook_row,
  is_published
from catalogue
on conflict (id) do update
set
  name = excluded.name,
  category = excluded.category,
  subtype = excluded.subtype,
  brand = excluded.brand,
  origin = excluded.origin,
  description = excluded.description,
  image_url = excluded.image_url,
